// Üretilen dosya: tool/ozgun/uret.py. Matematik · Fonksiyonlar ve grafik yorumu (metinle) (zor).
const ozMathematics7Zor = <(String, String, List<String>, String)>[
  ('Bir kuyudaki su seviyesi pompa çalışırken her saat sabit miktarda düşüyor. 3. saat sonunda seviye 21 m, 7. saat sonunda 9 m ise seviye kaçıncı saatin sonunda sıfıra iner?', '10', ['9', '11', '12'], 'Saatlik düşüş (21 − 9)/4 = 3 m\'dir. 9 m\'lik su 9/3 = 3 saatte biter; 7 + 3 = 10. saatin sonunda seviye sıfır olur.'),
  ('Bir firmanın aylık maliyeti M(x) = 4 000 + 35x, geliri G(x) = 60x TL\'dir (x: ürün adedi). Üretilen her ek ürünün kâra katkısı kaç TL\'dir?', '25', ['−4 000', '60', '95'], 'Kâr K(x) = G(x) − M(x) = 25x − 4 000\'dir. Kâr fonksiyonunun eğimi 25 olduğundan her ek ürün kârı 25 TL artırır.'),
  ('Ali\'nin birikimi 900 TL\'den başlayıp haftada 50 TL azalıyor, Veli\'ninki 200 TL\'den başlayıp haftada 90 TL artıyor. Kaçıncı haftanın sonunda Veli\'nin birikimi Ali\'ninkini ilk kez geçer?', '6', ['5', '7', '4'], '900 − 50h < 200 + 90h için 700 < 140h, h > 5 bulunur. 5. haftada ikisi de 650 TL\'dir; 6. haftada Veli geçer.'),
  ('Bir fotokopi merkezi sayfa başına 1,5 TL alıyor ya da 60 TL\'lik kartla sayfa başı 0,5 TL ücret uyguluyor. 50 sayfa çektirecek bir öğrenci için doğru değerlendirme hangisidir?', 'Kartsız seçenek 10 TL daha ucuzdur', ['Kartlı seçenek 10 TL daha ucuzdur', 'İki seçenek de aynı tutarı tutar, fark yoktur', 'Kartlı seçenek 25 TL daha ucuzdur'], 'Kartsız: 50·1,5 = 75 TL. Kartlı: 60 + 50·0,5 = 85 TL. Kartsız seçenek 10 TL avantajlıdır; eşitlik 60 sayfada olur.'),
  ('f fonksiyonu x < 0 için x + 3, x ≥ 0 için 3 − 2x kuralıyla tanımlanıyor. f(x) ≥ 1 koşulunu sağlayan x\'lerin oluşturduğu aralık hangisidir?', '[−2, 1]', ['[−2, 0)', '[−2, 0) ∪ (0, 1]', '(−2, 1)'], 'x < 0\'da x + 3 ≥ 1, x ≥ −2 verir. x ≥ 0\'da 3 − 2x ≥ 1, x ≤ 1 verir. Birleşim [−2, 1]\'dir.'),
  ('Bir vergi sisteminde gelirin ilk 10 000 TL\'si %10, aşan kısmı %20 oranında vergilendiriliyor. 25 000 TL gelirin vergisi toplam gelirin yüzde kaçıdır?', '16', ['15,5', '20', '12'], 'Vergi 1 000 + 0,2·15 000 = 4 000 TL\'dir. 4 000/25 000 = 0,16 yani %16 olur.'),
  ('Bir otoparkın ücreti her başlamış saat için 20 TL\'dir. Bu ücreti dakika cinsinden süre d > 0 için doğru veren ifade hangisidir?', '20·⌈d/60⌉', ['20·⌊d/60⌋', '20·⌊d/60⌋ + 20', '20·(d/60)'], 'Başlamış her saat tam ücretlendirildiğinden yukarı yuvarlama, yani tavan fonksiyonu gerekir. 20·⌊d/60⌋ + 20 ise tam 60 dakikada fazladan ücret alır.'),
  ('Bir öğrenci y = (x + 3)² grafiğinin y = x² grafiğinin 3 birim sağa ötelenmişi olduğunu söylüyor. Bu düşünce için doğru değerlendirme hangisidir?', 'Yanlıştır; grafik 3 birim sola ötelenmiştir', ['Doğrudur; işaret artı olduğu için sağa kayar', 'Yanlıştır; grafik 3 birim yukarı ötelenmiştir', 'Yanlıştır; grafik değişmez, yalnız daralır'], 'Yeni tepe noktası x + 3 = 0, yani x = −3\'tedir. Bu, eski tepe (0, 0)\'ın 3 birim solu demektir.'),
  ('Bir öğrenci, y = f(3x) dönüşümünün grafiği yatayda 3 kat genişlettiğini söylüyor. Bu iddia için doğru değerlendirme hangisidir?', 'Yanlıştır; yatayda 3\'te 1\'ine daraltır', ['Doğrudur; katsayı büyüdükçe grafik genişler', 'Yanlıştır; düşeyde 3 kat uzatır', 'Yanlıştır; grafiği 3 birim sola taşır'], 'f(3x)\'te eski (a, b) noktası (a/3, b)\'ye gider. Apsisler 3\'e bölündüğü için grafik y eksenine doğru sıkışır.'),
  ('y = √x grafiği önce y eksenine göre yansıtılıp sonra 3 birim sağa kaydırılırsa hangi fonksiyon elde edilir?', 'y = √(3 − x)', ['y = √(−x − 3)', 'y = −√(x − 3)', 'y = √(x + 3)'], 'Yansıma y = √(−x) verir. Sağa öteleme için x yerine x − 3 yazılır: √(−(x − 3)) = √(3 − x).'),
  ('Kuralda x yerine |x| yazılarak oluşturulan y = f(|x|) eğrisini, f\'nin eğrisinden çizmek için izlenecek yol hangisidir?', 'Sağ yarı korunur ve y eksenine göre sola yansıtılır; sol yarı atılır', ['Alt yarı x eksenine göre yukarı katlanır', 'Sol yarı korunur ve sağa yansıtılır', 'Grafik orijine göre yansıtılır'], 'x ≥ 0 için f(|x|) = f(x)\'tir; x < 0 için f(−x) olur. Böylece sağ yarının y eksenine göre simetriği sol tarafa çizilir.'),
  ('Gerçek sayılarda tanımlı bir çift fonksiyon (0, ∞) aralığında artansa (−∞, 0) aralığında nasıl davranır?', 'Azalandır', ['Artandır', 'Sabittir', 'Artan ya da azalan olabilir'], 'Grafik y eksenine göre aynadaki görüntü gibidir. Sağda yükselen eğri, solda sola doğru giderken yükselir; soldan sağa okunduğunda azalandır.'),
  ('Orijine göre simetrik bir eğri, x ≥ 0 bölgesinde soldan sağa yükseliyor. Bu eğri x ≤ 0 bölgesinde nasıl davranır?', 'Artandır', ['Azalandır', 'Sabittir', 'Önce azalır sonra artar'], 'Orijine göre simetri, sağdaki yükselişi sol tarafa da yükseliş olarak taşır. Örneğin x³ her yerde artandır.'),
  ('f herhangi bir fonksiyon, g çift fonksiyon olmak üzere f∘g bileşkesi için hangisi kesinlikle doğrudur?', 'Çifttir', ['Tektir', 'Ne tek ne çifttir', 'f\'nin türüne göre tek olabilir'], 'f(g(−x)) = f(g(x)) olduğundan, f ne olursa olsun bileşke çift fonksiyondur.'),
  ('Bir f fonksiyonunun grafiği x eksenini yalnız x = −2 ve x = 3\'te kesiyor; x < −2 için eksenin altında, −2 < x < 3 için üstünde, x > 3 için yeniden altında kalıyor. x · f(x) < 0 eşitsizliğini sağlayan aralıklardan biri hangisidir?', '(−2, 0)', ['(0, 3)', '(−∞, −2)', '(−2, 3) aralığının tamamı'], '−2 < x < 0\'da x negatif, f pozitiftir; çarpım negatiftir. (0, 3)\'te ikisi de pozitif, x < −2\'de ikisi de negatiftir.'),
  ('Grafiği (−3, 2)\'den (0, −4)\'e ve (0, −4)\'ten (4, 4)\'e uzanan iki doğru parçası olan bir fonksiyon için f(x) = k denkleminin tam iki çözümü olmasını sağlayan k değerlerinin aralığı nedir?', '(−4, 2]', ['[−4, 2]', '(−4, 4]', '(2, 4]'], 'Sol parça −4 ile 2 arasındaki değerleri, sağ parça −4 ile 4 arasındakileri alır. −4 < k ≤ 2 için her parçada birer çözüm vardır; k = −4\'te tek çözüm, 2 < k ≤ 4\'te yalnız sağ parçada çözüm olur.'),
  ('Bir f fonksiyonu [1, 4]\'te artan, [4, 9]\'da azalandır; f(1) = −2, f(4) = 6, f(9) = 0\'dır. f\'nin [1, 9]\'daki görüntü kümesi nedir?', '[−2, 6]', ['[0, 6]', '[−2, 0]', '[−2, 6] − {0}'], 'En büyük değer dönüm noktasında 6, en küçük değer uçlardan küçüğü olan −2\'dir. Sürekli olduğu varsayılan grafik aradaki her değeri alır.'),
  ('Bir depoya su eşit hızla akarken depo silindir biçimindedir. Su yüksekliği-zaman grafiği nasıl görünür?', 'Sabit eğimli bir doğru', ['Gittikçe dikleşen bir eğri', 'Gittikçe yataylaşan bir eğri', 'Basamaklı bir çizgi'], 'Silindirde kesit alanı sabit olduğundan eşit sürelerde eşit yükseklik artışı olur; grafik doğrusaldır.'),
  ('Eşit hızla su doldurulan bir kabın altı geniş, üstü dar ise su yüksekliği-zaman grafiği nasıl değişir?', 'Başta yavaş, sonra giderek hızlı yükselir', ['Başta hızlı, sonra giderek yavaş yükselir', 'Baştan sona hep aynı hızla, düzgün biçimde yükselir', 'Önce yükselir, sonra alçalır'], 'Geniş kısımda aynı hacim daha az yükseklik oluşturur; kap daraldıkça aynı hacim daha çok yükseklik verir. Bu yüzden eğri gittikçe dikleşir.'),
  ('Bir f fonksiyonu (−∞, −1) ve (2, ∞) aralıklarında negatif, (−1, 2) aralığında pozitiftir. g(x) = f(x − 3) fonksiyonu hangi aralıkta pozitiftir?', '(2, 5)', ['(−4, −1)', '(−1, 2)', '(2, 5) ∪'], 'g(x) > 0 için −1 < x − 3 < 2 olmalıdır; bu 2 < x < 5 verir.'),
  ('Bir fonksiyonun grafiği (−5, 0)\'dan (−2, 4)\'e yükselip (1, 4)\'e yatay ilerliyor, sonra (3, 0)\'a iniyor. f(x) = 4 denkleminin kaç çözümü vardır?', 'Sonsuz sayıda', ['1', '2', '3'], 'Grafiğin (−2, 4) ile (1, 4) arasındaki yatay parçasındaki her nokta y = 4 üzerindedir. Bu nedenle sonsuz sayıda x için f(x) = 4 olur.'),
  ('Bir öğrenci, x eksenini hiç kesmeyen ve tamamen eksenin altında kalan bir grafiğin azalan olması gerektiğini söylüyor. Hangi örnek bu iddiayı çürütür?', 'f(x) = −1/x, x > 0', ['f(x) = −x, x > 0', 'f(x) = −x², x > 0', 'f(x) = −2x − 1, x > 0'], 'x > 0 için −1/x her zaman negatiftir ama x büyüdükçe sıfıra yaklaşarak artar. Negatif olmak azalan olmak demek değildir.'),
  ('f fonksiyonu x = 1\'de en büyük değeri olan 6\'yı alıyor. g(x) = −f(x) fonksiyonu için hangisi doğrudur?', 'x = 1\'de en küçük değeri −6\'dır', ['x = 1\'de en büyük değeri −6\'dır', 'x = −1\'de en küçük değeri 6 olur, çünkü apsis de yansır', 'x = −1\'de en büyük değeri 6\'dır'], 'x eksenine göre yansıma en yüksek noktayı en alçak noktaya çevirir; apsis aynı kalır, değerin işareti değişir.'),
  ('Bir arabanın 0–10 saniyelik hız grafiği yataydır ve 72 km/sa değerindedir. Bu sürede araç kaç metre yol almıştır?', '200', ['720', '72', '20'], '72 km/sa = 20 m/s\'dir. Hız sabit olduğundan 10 saniyede 20·10 = 200 m yol alınır.'),
  ('Bir f fonksiyonunun eğrisi y ekseninin solunda x ekseninin altında, sağında x ekseninin üstünde kalıyor. f(−x) fonksiyonu x = −5 noktasında hangi işaretli değeri alır?', 'Pozitif', ['Negatif', 'Sıfır', 'Belirlenemez'], 'f(−(−5)) = f(5) olup 5 pozitif bölgede olduğundan değer pozitiftir.'),
  ('f(x) = 2ˣ fonksiyonunun [0, 1], [1, 2] ve [2, 3] aralıklarındaki ortalama değişim hızları sırasıyla nedir?', '1, 2, 4', ['2, 2, 2', '1, 2, 3', '2, 4, 8'], 'Değerler 1, 2, 4, 8\'dir. Ardışık farklar 1, 2, 4 olup aralık uzunluğu 1 olduğundan hızlar da bunlardır; üstel büyümede hız da katlanarak artar.'),
  ('A = {1, 2, 3} kümesinde h eşlemesi 1 → 2, 2 → 3, 3 → 1 biçimindedir. h fonksiyonu kendisiyle kaç kez bileşkelenirse ilk kez birim fonksiyon elde edilir (h, h∘h, h∘h∘h, ... sırasıyla)?', '3', ['2', '6', '4'], 'h∘h eşlemesi 1 → 3, 2 → 1, 3 → 2\'dir. h∘h∘h ise her elemanı kendisine götürür; üçüncü adımda birim fonksiyon oluşur.'),
  ('Bir mağazada %20 zam ve 30 TL indirim farklı sırayla uygulanıyor: önce indirim, sonra zam. Bu sıra, önce zam sonra indirim sırasına göre müşteriye nasıl yansır?', '6 TL daha az fiyat verir', ['6 TL daha fazla fiyat verir', 'İki sıra aynı fiyatı verir', '30 TL daha az fiyat verir'], 'Önce indirim: 1,2(x − 30) = 1,2x − 36. Önce zam: 1,2x − 30. Fark 6 TL olup ilk sıra daha ucuzdur.'),
  ('Bir döviz bürosu TL\'yi dolara d(x) = x/40 ile, doları avroya a(y) = 0,9y ile çeviriyor. 3 600 TL\'nin önce dolara sonra avroya çevrilmesiyle kaç avro elde edilir?', '81', ['90', '72', '97,2'], 'd(3 600) = 90 dolar, a(90) = 81 avrodur.'),
  ('Bir şirketin geliri 2018\'de 40, 2020\'de 40 milyon TL\'dir. Bir yorumcu \'Bu iki yıl arasında gelir hiç değişmemiştir\' diyor. Bu yorum için en doğru değerlendirme hangisidir?', 'Ortalama değişim 0\'dır ama aradaki dalgalanmalar bilinemez', ['Doğrudur; gelir iki yıl boyunca her an 40 milyon TL düzeyindedir', 'Yanlıştır; gelir mutlaka azalmıştır', 'Doğrudur; çünkü fonksiyon sabittir'], 'Ortalama değişim hızı yalnız iki uç değere bakar. Aradaki dönemde gelir artıp azalmış olabilir.'),
  ('Kilometreyi mile çeviren fonksiyon M(k) = 0,62k ise mili kilometreye çeviren fonksiyonun eğimi yaklaşık kaçtır?', '1,61', ['0,62', '0,38', '1,38'], 'Ters fonksiyon k = m/0,62 olup eğimi 1/0,62 ≈ 1,61\'dir. Doğrusal fonksiyonun tersinin eğimi, eğimin çarpmaya göre tersidir.'),
  ('Birebir ve artan bir f fonksiyonunun grafiği y = x doğrusunu yalnız (3, 3) noktasında kesiyor. f⁻¹\'in grafiği hakkında hangisi kesindir?', '(3, 3) noktasından geçer', ['Orijinden geçer', 'Azalan bir fonksiyondur', 'y = x doğrusunu hiç kesmez'], 'y = x üzerindeki noktalar bu doğruya göre yansımada yerinde kalır. Bu yüzden (3, 3) ters fonksiyonun grafiğinde de bulunur.'),
  ('1 ile 5 arasındaki girdileri 2 ile 10 arasındaki çıktılara birebir ve örten biçimde eşleyen bir f fonksiyonunun tersinin tanım kümesi nedir?', '[2, 10]', ['[1, 5]', '[1, 10]', '[2, 5]'], 'Tersin tanım kümesi, asıl fonksiyonun görüntü kümesidir; görüntü kümesi ise asıl fonksiyonun tanım kümesidir.'),
  ('f(x) = x ve g(x) = x − 3 artan fonksiyonlar. Bir öğrenci f·g çarpımının da artan olması gerektiğini söylüyor. Bu iddia için doğru değerlendirme hangisidir?', 'Yanlıştır; x² − 3x, x < 1,5 için azalandır', ['Doğrudur; artanların çarpımı hep artandır', 'Yanlıştır; çarpım her yerde azalandır', 'Doğrudur; çünkü iki fonksiyon da doğrusaldır'], 'f·g = x² − 3x bir paraboldür ve tepe noktası x = 1,5\'tedir; bu noktanın solunda azalır.'),
  ('Her x için f(x) + f(2 − x) = 0 eşitliğini sağlayan bir fonksiyonun grafiği hangi noktaya göre simetriktir?', '(1, 0)', ['(2, 0)', '(0, 1)', '(1, 1) noktası'], 'x ve 2 − x noktalarının orta noktası 1\'dir ve bu noktalardaki değerler birbirinin ters işaretlisidir. Bu, (1, 0) noktasına göre simetri demektir.'),
  ('Bir göldeki nilüferlerin kapladığı alan her gün iki katına çıkıyor ve göl 30. günde tamamen kaplanıyor. Göl kaçıncı günde yarı yarıya kaplanmıştır?', '29', ['15', '28', '20'], 'Alan her gün ikiye katlandığından tam kaplanmadan bir gün önce göl yarı kaplıdır.'),
  ('A planında birikim her ay 1 000 TL artıyor, B planında birikim 10 TL\'den başlayıp her ay ikiye katlanıyor. Uzun dönem için doğru değerlendirme hangisidir?', 'B planı bir noktadan sonra A\'yı geçer ve fark hızla açılır', ['A planı sabit artışı sayesinde her zaman önde kalmaya devam eder', 'İki plan hiçbir zaman eşitlenmez', 'B planı yalnız ilk aylarda öndedir'], 'Üstel büyüme başta yavaş görünse de katlanarak artar; doğrusal büyüme ise sabit hızda kalır. Yeterince uzun sürede üstel olan her zaman öne geçer.'),
  ('Bir dik üçgenin dik kenarlarından biri x, diğeri 10 − x cm\'dir. Hipotenüs uzunluğunu x cinsinden veren fonksiyon hangisidir?', '√(2x² − 20x + 100)', ['√(100 − 20x)', '√(100 − 2x²)', '√(2x² + 100)'], 'Hipotenüs² = x² + (10 − x)² = x² + 100 − 20x + x² = 2x² − 20x + 100\'dür.'),
  ('\'y eksenine göre simetrik, en küçük değeri 0 olan ve bu değeri yalnız orijinde alan, orijinde sivri bir köşesi bulunan\' grafik hangi fonksiyona aittir?', 'y = |x|', ['y = x²', 'y = x³', 'y = √|x| + 1'], 'x² de simetrik ve en küçük değeri 0\'dır, ancak orijinde yumuşak bir dip yapar. Sivri köşe mutlak değer fonksiyonunun özelliğidir.'),
  ('\'Grafiği iki ayrı koldan oluşan, x = 0\'da tanımsız, iki ekseni de asimptot kabul eden ve ikinci ile dördüncü bölgede yer alan\' fonksiyon hangisidir?', 'y = −2/x', ['y = 2/x', 'y = 1/x²', 'y = −x'], 'k/x biçimindeki fonksiyonlar iki eksene asimptotiktir; k < 0 olunca kollar ikinci ve dördüncü bölgeye düşer.'),
  ('Grafiği x = 3 doğrusuna göre simetrik olan bir f fonksiyonu için f(1) = 8 ise f\'nin kesinlikle bildiğimiz başka bir değeri hangisidir?', 'f(5) = 8', ['f(−1) = 8', 'f(3) = 8', 'f(1) = −8'], 'x = 3\'e göre simetride 1\'in karşılığı 3 + (3 − 1) = 5\'tir. Bu iki nokta aynı yükseklikte olduğundan f(5) = 8\'dir.'),
  ('Bir öğrenci \'x büyüdükçe artan ama hiçbir zaman 5\'i aşmayan\' bir fonksiyon örneği arıyor. Hangi seçenek bu koşula uyar (x > 0)?', 'y = 5 − 1/x', ['y = 5 + 1/x', 'y = 5x', 'y = 5 − x'], 'x > 0\'da 1/x azaldığından 5 − 1/x artar ve 5\'e yaklaşır ama ulaşmaz. 5 + 1/x azalandır, diğerleri ise 5\'i aşar ya da azalır.'),
  ('İki koşucunun başlangıçtan uzaklıkları A için d = 5t, B için d = 3t + 20 metredir (t saniye). Hangi anda A, B\'ye yetişir ve bu anda başlangıçtan kaç metre uzaktadırlar?', '10. saniyede, 50 m', ['20. saniyede, 100 m', '5. saniyede, 25 m', '10. saniyede, 30 m'], '5t = 3t + 20 ise t = 10 s\'dir. Bu anda d = 50 m\'dir.'),
  ('Bir asansörün zemin kattan yüksekliği ilk 10 saniyede 0\'dan 30 m\'ye doğrusal çıkıyor, 15 saniye bekliyor, sonra 15 saniyede 12 m\'ye iniyor. Asansör toplam kaç metre yol almıştır?', '48', ['30', '42', '18'], 'Çıkışta 30 m, inişte 30 − 12 = 18 m yol alınır. Toplam yol 48 m\'dir; konumdaki net değişim ise 12 m\'dir.'),
  ('Bir ürünün talebi fiyat p TL iken T(p) = 500 − 4p adet, arzı ise A(p) = 6p − 100 adettir. Arz ile talebin eşit olduğu denge fiyatı kaç TL\'dir?', '60', ['50', '100', '75'], '500 − 4p = 6p − 100 ise 600 = 10p, p = 60 TL\'dir. Bu fiyatta arz ve talep 260 adettir.'),
  ('Asılmamışken boyu 30 cm olan bir yay, her 100 g için 4 cm uzuyor. Yayın toplam boyunu kütle m (g) cinsinden veren fonksiyon hangisidir?', 'L(m) = 30 + 0,04m', ['L(m) = 30m + 0,04', 'L(m) = 0,04m', 'L(m) = 30 + 4m'], 'Başlangıç boyu 30 cm sabit terimdir; gram başına uzama 4/100 = 0,04 cm eğimdir.'),
  ('Bir metal çubuğun uzunluğu sıcaklık T (°C) için L(T) = 200 + 0,0024T cm ile veriliyor. Sıcaklık 0 °C\'den 50 °C\'ye çıkınca uzunluk kaç cm artar?', '0,12', ['0,024', '1,2', '200,12'], 'Artış 0,0024·50 = 0,12 cm\'dir. 200,12 artış değil yeni uzunluktur.'),
  ('Bir çiftçi çitin bir kenarını ahır duvarı yaparak 60 m tel ile dikdörtgen bir alan çeviriyor. Duvara dik kenarlar x m ise alanı veren fonksiyon hangisidir?', 'A(x) = x(60 − 2x)', ['A(x) = x(60 − x)', 'A(x) = x(30 − x)', 'A(x) = 2x(60 − x)'], 'İki dik kenar 2x m tel kullanır; duvara paralel kenar 60 − 2x m olur. Alan x(60 − 2x)\'tir.'),
  ('Bir öğretmen \'Sınav notu çalışma süresinin bir fonksiyonudur\' diyor. Bu ifadenin matematiksel anlamı hangisidir?', 'Her çalışma süresine tek bir not karşılık gelir', ['Her nota tek bir çalışma süresi karşılık gelir', 'Çalışma süresi arttıkça not da mutlaka ve her zaman artar', 'Not ile süre doğru orantılıdır'], 'Fonksiyon olmanın tek şartı her girdinin tek çıktısının olmasıdır. Artanlık ya da orantı bu ifadeden çıkmaz.'),
  ('Bir şehirdeki günlük su tüketimi gün sayısının fonksiyonu olarak S(g) ile gösteriliyor. S(g + 1) − S(g) < 0 ifadesi ne anlatır?', 'Ertesi gün tüketim bir önceki güne göre azalmıştır', ['Tüketim her gün sıfırdan küçüktür', 'Tüketim bir günde iki katına çıkmıştır', 'Ertesi gün tüketim bir önceki güne göre artmış, yükselmiştir'], 'Ardışık iki gün arasındaki farkın negatif olması, sonraki günün değerinin daha küçük olduğunu gösterir.'),
  ('Bir şirket iki makine arasında seçim yapıyor: A makinesi 50 000 TL\'ye alınıp ürün başına 8 TL maliyetle, B makinesi 20 000 TL\'ye alınıp ürün başına 14 TL maliyetle çalışıyor. Yılda 4 000 ürün üretilecekse hangisi doğru değerlendirmedir?', 'B daha ekonomiktir; fark 6 000 TL\'dir', ['A daha ekonomiktir; fark 6 000 TL\'dir', 'İki makine eşit maliyetlidir', 'A daha ekonomiktir; fark 30 000 TL\'dir'], 'A: 50 000 + 32 000 = 82 000 TL. B: 20 000 + 56 000 = 76 000 TL. Bu üretim düzeyinde B 6 000 TL daha ucuzdur; A ancak 5 000 üründen sonra avantajlı olur.'),
  ('Bir otoparkta ücret, d dakika için 30·⌊d/60⌋ TL olarak hesaplanıyor. Bu kurala göre 59 dakika park eden bir sürücü için doğru yorum hangisidir?', 'Hiç ücret ödemez; kural aşağı yuvarlar', ['30 TL öder; kural yukarı yuvarlar', '59 TL öder', '15 TL öder; çünkü 59 dakika yarım saatten fazladır'], '⌊59/60⌋ = ⌊0,98⌋ = 0\'dır; bu kural tam saatleri sayar ve ilk saati ücretsiz bırakır.'),
  ('Bir çocuğun boyu 2 yaşında 85 cm, 6 yaşında 115 cm\'dir. Doğrusal modelle 30 yaşındaki boyu 295 cm bulunuyor. Bu sonuç için doğru değerlendirme hangisidir?', 'Model ölçüm aralığının çok dışına taşınmıştır; sonuç güvenilmez', ['Doğrusal model her yaşta doğru sonuç verir', 'Hesap hatalıdır; doğru sonuç 315 cm\'dir', 'Büyüme üstel olduğundan sonuç daha da büyük olmalıdır'], 'Doğrusal model ölçülen aralıkta makul olabilir, ama insan büyümesi ergenlikten sonra durur. Veri aralığının çok dışına tahmin (dış değerleme) güvenilmezdir.'),
  ('f fonksiyonu santimetre cinsinden kenar uzunluğundan cm² cinsinden alanı veriyor: f(x) = x². Aynı alanı m² cinsinden, kenarı metre cinsinden alan g fonksiyonuyla g(1) değeri kaçtır?', '1', ['10 000', '0,0001', '100'], 'g(y) = y² m²\'dir; kenarı 1 m olan karenin alanı 1 m²\'dir. Hem girdi hem çıktı birimi değiştiğinden kural aynı kalır.'),
  ('y = |x| grafiği düşeyde 2 kat uzatılıp sonra 4 birim aşağı kaydırılırsa grafiğin x eksenini kestiği noktalar arasındaki uzaklık kaçtır?', '4', ['8', '2', '6'], 'Yeni fonksiyon 2|x| − 4\'tür. 2|x| = 4 ise x = ±2; aralarındaki uzaklık 4\'tür.'),
  ('y = f(x) ile y = f(x − 3) grafikleri aynı biçimdedir. Bu iki grafik arasındaki ilişkiyi en iyi hangi ifade anlatır?', 'Biri diğerinin 3 birim sağa ötelenmiş kopyasıdır', ['Biri diğerinin 3 kat genişletilmişidir', 'Biri diğerinin 3 birim yukarı ötelenmişidir', 'Biri diğerinin x = 3 doğrusuna göre yansımasıdır'], 'x yerine x − 3 yazmak grafiği biçimini bozmadan 3 birim sağa taşır.'),
  ('⌊x⌋ fonksiyonu kullanılarak bir sayıyı en yakın tam sayıya yuvarlayan (yarımlar yukarı) ifade hangisidir?', '⌊x + 0,5⌋', ['⌊x⌋ + 0,5', '⌊x − 0,5⌋', '⌊2x⌋/2'], 'Örneğin x = 2,6 için ⌊3,1⌋ = 3; x = 2,4 için ⌊2,9⌋ = 2 olur. Yarımlar da ⌊3⌋ = 3 gibi yukarı yuvarlanır.'),
  ('Bir oda sıcaklığı Celsius cinsinden C(t) = 18 + 0,5t ile artıyor (t dakika). Kelvin cinsinden sıcaklığı veren fonksiyonun eğimi kaçtır?', '0,5', ['273,5', '0,9', '1,8'], 'Kelvin = Celsius + 273,15\'tir; bu yalnız sabit terimi değiştirir. Her iki ölçekte bir derecelik aralık aynı büyüklükte olduğundan eğim 0,5 kalır.'),
  ('f\'nin grafiği (0, 4) ile (4, 0) noktalarını birleştiren doğru parçası, g\'nin grafiği ise (0, 0) ile (4, 4)\'ü birleştiren doğru parçasıdır. (f∘g)(1) kaçtır?', '3', ['1', '4', '2,5'], 'g(x) = x olduğundan g(1) = 1\'dir. f(x) = 4 − x olduğundan f(1) = 3 bulunur.'),
  ('Bir f fonksiyonunun grafiği (−2, 3), (1, −1) ve (3, 1) noktalarından geçiyor (başka bilgi gerekmiyor). (f∘f)(3) kaçtır?', '−1', ['3', '1', '−3'], 'f(3) = 1 ve f(1) = −1\'dir. Bu yüzden f(f(3)) = −1 olur.'),
  ('f\'nin sıfırları yalnız −1 ve 2\'dir; g(x) = x² olarak veriliyor. (f∘g)(x) = 0 denkleminin gerçek çözümleri hangileridir?', 'x = √2 ve x = −√2', ['x = −1 ve x = 2', 'x = 1 ve x = 4', 'x = ±1 ve x = ±√2'], 'f(g(x)) = 0 için g(x) = −1 ya da g(x) = 2 olmalıdır. x² = −1\'in gerçek çözümü yoktur; x² = 2\'den x = ±√2 gelir.'),
  ('f fonksiyonunun grafiği (0, 1) noktasından (4, 9) noktasına giden tek bir doğru parçasıdır. Tersinin grafiği hangi iki noktayı birleştiren doğru parçasıdır?', '(1, 0) ve (9, 4)', ['(0, 1) ve (9, 4)', '(−1, 0) ve (−9, −4)', '(1, 0) ve (4, 9)'], 'Tersin grafiği y = x\'e göre yansımadır; her noktanın koordinatları yer değiştirir.'),
  ('f\'nin görüntü kümesi [2, 7] ve g\'nin tanım kümesi [0, 5] ise g∘f bileşkesi f\'nin tanım kümesinin tamamında tanımlı olur mu?', 'Hayır; f\'nin 5\'i aşan çıktıları g\'ye girdi olamaz', ['Evet; görüntü kümesi tanım kümesini kapsar', 'Evet; iki küme de 5 birim uzunluğundadır', 'Hayır; çünkü f\'nin hiçbir çıktısı g\'ye girdi olamaz'], 'g∘f\'nin tanımlı olması için f\'nin çıktıları g\'nin tanım kümesinde olmalıdır. (5, 7] aralığındaki çıktılar [0, 5]\'in dışındadır.'),
  ('Bir öğrenci uzaklık-zaman eğrisindeki yatay bölümle hız-zaman eğrisindeki yatay bölümü aynı anlamda yorumluyor. Doğru düzeltme hangisidir?', 'İlki durmayı, ikincisi sabit hızla gitmeyi gösterir', ['İkisi de durmayı gösterir', 'İlki sabit hızla hareketi, ikincisi ise durmayı gösterir', 'İkisi de sabit hızla hareketi gösterir'], 'Uzaklık değişmiyorsa hareket yoktur; hız değişmiyorsa hareket sabit hızla sürüyordur.'),
  ('Bir mağazanın gelir fonksiyonu G(x) TL ve maliyet fonksiyonu M(x) TL\'dir. G(x) > M(x) ifadesi iki eğrinin çizimi üzerinde neye karşılık gelir?', 'Gelir eğrisinin maliyet eğrisinin üstünde olması', ['İki eğrinin kesişmesi', 'Maliyet eğrisinin yatay ekseni bir noktada kesmesi', 'Gelir eğrisinin azalan olması'], 'Aynı x için gelir daha büyükse gelir eğrisi o bölgede yukarıdadır; bu durum kâr anlamına gelir.'),
  ('f(x) > 0 eşitsizliği yalnız (1, 5) aralığında sağlanıyor. g(x) = f(2x) için g(x) > 0 hangi aralıkta sağlanır?', '(1/2, 5/2)', ['(2, 10)', '(1, 5)', '(−1, 3)'], '1 < 2x < 5 olmalıdır; bu 1/2 < x < 5/2 verir.'),
  ('Pozitif değerleri yalnız −3 ile 2 arasında (uçlar hariç) alan bir f için, girdisinin işareti değiştirilmiş h(x) = f(−x) kuralı hangi x\'lerde pozitif olur?', '(−2, 3)', ['(−3, 2)', '(2, 3)', '(−3, −2)'], '−3 < −x < 2 ise −2 < x < 3\'tür; y eksenine göre yansıma aralığı da yansıtır.'),
  ('Bir trenin hızı 0\'dan başlayarak 60 saniyede düzgün biçimde 30 m/s\'ye çıkıyor. Bu sürede tren kaç metre yol almıştır?', '900', ['1 800', '450', '30'], 'Düzgün hızlanmada ortalama hız (0 + 30)/2 = 15 m/s\'dir; 60 saniyede 15·60 = 900 m alınır.'),
  ('f fonksiyonu [0, 3]\'te artan, [3, 6]\'da azalan ve f(0) = f(6) = 0\'dır. g(x) = f(x) − 2 fonksiyonunun [0, 6]\'da en fazla kaç sıfırı olabilir?', '2', ['1', '3', '4'], 'g = 0 demek f = 2 demektir. Artan parça 2\'yi en çok bir kez, azalan parça da en çok bir kez geçer; en fazla iki çözüm vardır.'),
  ('Basit sarkacın periyodu ip uzunluğunun kareköküyle orantılıdır. Periyodu iki katına çıkarmak için ip uzunluğu kaç katına çıkarılmalıdır?', '4', ['2', '√2', '8'], 'T ∝ √L ise 2T için √(L\') = 2√L olmalıdır; buradan L\' = 4L bulunur.'),
  ('Işık şiddeti kaynağa uzaklığın karesiyle ters orantılıdır. Uzaklık 3 katına çıkarsa ışık şiddeti nasıl değişir?', 'Dokuzda birine iner', ['Üçte birine iner', '9 katına çıkar', 'Altıda birine iner'], 'I ∝ 1/d² olduğundan d 3 katına çıkınca I, 1/3² = 1/9 katına iner.'),
  ('Toplam maliyeti M(x) = 2 000 + 5x olan bir ürün için birim başına ortalama maliyet O(x) = M(x)/x\'tir. Üretim arttıkça O(x) nasıl davranır?', 'Azalarak 5\'e yaklaşır', ['Artarak 5\'e yaklaşır', 'Sabit olarak 5\'tir', 'Azalarak sıfıra yaklaşır'], 'O(x) = 2 000/x + 5\'tir; sabit gider daha çok ürüne dağıldıkça ilk terim küçülür ve ortalama maliyet 5\'e yaklaşır.'),
  ('x değerleri 0, 1, 2, 3 iken y değerleri 2, 6, 18, 54 olarak veriliyor. Bu ilişki için doğru yorum hangisidir?', 'Üsteldir; y = 2·3ˣ', ['Doğrusaldır; y = 4x + 2', 'Üsteldir; y = 3·2ˣ', 'İkinci derecedendir; y = 6x² + 2'], 'Ardışık oranlar sabit 3\'tür; başlangıç değeri 2\'dir. Bu y = 2·3ˣ üstel kuralını verir.'),
  ('Bir öğrenci \'y = 1/x² fonksiyonu tek fonksiyondur çünkü 1/x tek fonksiyondur\' diyor. Bu düşünce için doğru değerlendirme hangisidir?', 'Yanlıştır; 1/x² çift fonksiyondur', ['Doğrudur; paydaları benzerdir', 'Yanlıştır; 1/x² ne tek ne çifttir', 'Doğrudur; ikisinin de x = 0\'da tanımı yoktur'], '1/(−x)² = 1/x² olduğundan fonksiyon çifttir; grafiği y eksenine göre simetriktir ve her iki kolu x ekseninin üstündedir.'),
  ('f(x) = x/2 + 6 işlemi 0\'dan başlayarak art arda uygulanırsa elde edilen sayılar hangi değere yaklaşır?', '12', ['6', 'Sonsuza', '0'], '0, 6, 9, 10,5, 11,25 ... diye ilerler; her adımda 12\'ye olan uzaklık yarıya iner. Değerler sabit nokta olan 12\'ye yaklaşır.'),
  ('f(x) = (x + 1)/(x − 3) fonksiyonunun görüntü kümesi, tersinin tanım kümesi düşünülerek bulunursa hangisi olur?', 'ℝ − {1}', ['ℝ − {3}', 'ℝ − {−1}', 'ℝ'], 'y = (x + 1)/(x − 3) ise x = (3y + 1)/(y − 1) olur. Ters ifade y = 1\'de tanımsızdır; bu yüzden f 1 değerini hiç almaz.'),
  ('Bir sayıyı iki katının bir fazlasına götüren kuralın tersi 15 sayısına art arda iki kez uygulanırsa hangi sayı elde edilir?', '3', ['7', '31', '3,5'], 'f⁻¹(x) = (x − 1)/2\'dir. f⁻¹(15) = 7, f⁻¹(7) = 3 olur.'),
  ('Bir yüzme havuzundaki su yüksekliği h (m) ve havuz derinliği 2,5 m\'dir. Su hacmi V(h) = 50h m³ ise V\'nin görüntü kümesi hangisidir?', '[0, 125]', ['[0, 50]', '[0, 2,5]', '[50, 125]'], 'h, 0 ile 2,5 arasında değişir; V(0) = 0 ve V(2,5) = 125\'tir.'),
  ('Sayı doğrusunda x noktasının 0\'a ve 2\'ye uzaklıkları toplamı |x| + |x − 2| ile verilir. Bu toplamın alabileceği değerler kümesi nedir?', '[2, ∞)', ['[0, ∞)', '(2, ∞)', '[0, 2]'], 'Sayı doğrusunda 0 ve 2\'ye uzaklıkların toplamı en az 2\'dir (x, 0 ile 2 arasındayken) ve sınırsız artabilir.'),
  ('Bir öğrencinin günlük cep harçlığı H(g) = 50 + 10g TL modeliyle yaptığı ödev sayısı g\'ye bağlanıyor. Bir arkadaşı \'H(−3) = 20 TL, yani 3 ödev eksik yapan 20 TL alır\' diyor. Doğru değerlendirme hangisidir?', 'Yanlıştır; negatif ödev sayısı modelin tanım kümesinde değildir', ['Doğrudur; kurala göre hesap doğrudur', 'Yanlıştır; H(−3) değeri aslında 80 TL olarak hesaplanmalıdır', 'Doğrudur; model her gerçek sayı için anlamlıdır'], 'Hesap kural bakımından doğru olsa da ödev sayısı negatif olamaz; bu girdi bağlamın tanım kümesi dışında kalır.'),
  ('Bir doğrusal yol üzerindeki 2., 5. ve 11. kilometrelerde ev var. Yola kurulacak bir postanenin evlere uzaklıkları toplamını en aza indirmek için postane kaçıncı kilometreye kurulmalıdır?', '5', ['6', '2', '11'], 'Uzaklıklar toplamı f(x) = |x − 2| + |x − 5| + |x − 11| olup ortanca nokta x = 5\'te en küçüktür: 3 + 0 + 6 = 9 km.'),
  ('Bir banyo küveti doldurulurken musluk bir süre kapatılıyor, sonra yeniden açılıyor ve en sonunda tıpa çekiliyor. Su hacmi-zaman eğrisinde kaç ayrı yatay bölüm vardır (tıpa çekildikten sonra küvet tamamen boşalıp öyle kalıyor)?', '2', ['1', '3', '0'], 'Musluğun kapalı olduğu süre ve küvet boşaldıktan sonraki süre hacmin değişmediği iki yatay bölümdür.'),
  ('Bir koşucu bir parkurda önce yavaş başlayıp giderek hızlanıyor. Başlangıçtan uzaklık-zaman eğrisinin biçimi hangisidir?', 'Gittikçe dikleşen artan eğri', ['Gittikçe yataylaşan artan eğri', 'Sabit eğimli bir doğru', 'Azalan bir eğri'], 'Uzaklık-zaman eğrisinin eğimi hızdır; hız arttıkça eğim de artar ve eğri dikleşir.'),
  ('Bir ürünün satışı piyasaya çıktıktan sonra hızla artıyor, bir süre sonra artış yavaşlıyor ve satış belirli bir düzeyde dengeleniyor. Toplam satış-zaman eğrisi nasıl bir biçimdedir?', 'S biçimli; başta yavaş, ortada hızlı, sonda doygun', ['Sürekli ve giderek daha da dikleşerek yükselen üstel eğri', 'Tepe yapıp sıfıra inen eğri', 'Basamaklı kesikli çizgi'], 'Yavaş başlangıç, hızlı yayılma ve doygunluk aşamaları S biçimli (lojistik) büyüme eğrisini oluşturur.'),
  ('Bir kişinin evden markete yürüyüp alışveriş yaptıktan sonra aynı yoldan eve dönmesini gösteren evden uzaklık-zaman eğrisi hangi noktada biter?', 'Zaman ekseni üzerinde', ['Başladığı noktanın üstünde, evden en uzak konumda', 'En yüksek noktada', 'Negatif uzaklıkta'], 'Eve dönüldüğünde evden uzaklık yeniden 0 olur; eğri zaman ekseni üzerinde biter.'),
  ('Bir kapta su ısıtılırken sıcaklık 100 °C\'ye kadar artıyor, kaynama sırasında bir süre sabit kalıyor. Sıcaklık-zaman eğrisinin bu sabit bölümünde hangisi doğrudur?', 'Isı verilmeye devam etse de sıcaklık değişmez', ['Isıtma durdurulmuş ve ocak tamamen kapatılmıştır', 'Sıcaklık azalmaktadır', 'Su donmaktadır'], 'Kaynama sırasında verilen enerji hâl değişimine harcanır; sıcaklık sabit kalır ve eğri yatay görünür.'),
  ('Bir haber sitesi bir şehrin nüfusunun hızla arttığını gösteren bir çizim yayımlıyor; çizimin dikey ekseni 0\'dan değil 950 binden başlıyor. Bu çizimle ilgili en doğru eleştiri hangisidir?', 'Eksen sıfırdan başlamadığı için küçük artış büyük görünebilir', ['Dikey eksen bu tür çizimlerde her zaman 1 milyondan başlatılmalıdır', 'Nüfus artışı grafikle gösterilemez', 'Zaman ekseni dikey olmalıdır'], 'Eksenin kesik başlaması eğimi görsel olarak abartır; değerlendirme yapılırken gerçek değişim miktarına bakılmalıdır.'),
  ('Bir arabanın deposu doluyken yola çıkılıyor, yolda bir kez depo tamamen dolduruluyor. Depodaki yakıt-mesafe grafiğinde dolum anında ne görülür?', 'Düşey bir sıçrama', ['Yatay bir bölüm', 'Eğimin işaret değiştirmeden azalması', 'Grafiğin x eksenine değmesi'], 'Dolum çok kısa sürede ve araç ilerlemeden olduğundan yakıt miktarı aynı mesafede birden artar; grafikte sıçrama görülür.'),
  ('Bir hastanın vücut sıcaklığı ilaç alındıktan sonra 2 saat boyunca düşüyor, sonra yeniden yükseliyor. Sıcaklık fonksiyonunun ilaç alındıktan 2 saat sonra hangi özelliği vardır?', 'Yerel en küçük değerini alır', ['Yerel en büyük değerini alır', 'Tanımsızdır', 'Sıfır değerini alır'], 'Azalma ve ardından artma, o anda bir yerel en düşük noktaya (çukura) işaret eder.'),
  ('Bir göldeki balık sayısı her yıl %10 artıyor, ama her yıl sonunda 50 balık avlanıyor. Başlangıçta 500 balık varsa balık sayısı zamanla nasıl değişir?', 'Sabit kalır', ['Üstel olarak artar', 'Doğrusal olarak azalır', 'Sıfıra iner'], '500\'ün %10\'u 50\'dir; yıl boyunca eklenen 50 balık yıl sonunda avlanır. Bu denge noktasında sayı 500\'de sabit kalır.'),
  ('Bir işletmenin aylık geliri yılın her ayında bir önceki aydan 2 000 TL fazla. Toplam (birikimli) gelir-ay grafiği nasıl görünür?', 'Gittikçe dikleşen artan eğri', ['Sabit eğimli doğru', 'Gittikçe yataylaşan eğri', 'Basamaksız yatay doğru'], 'Aylık gelir doğrusal artarsa toplamdaki aylık artış her ay büyür; birikimli gelir eğrisi dikleşir.'),
  ('Buz-su karışımı içeren bir bardak sıcak bir odada bırakılıyor. Bardaktaki suyun sıcaklığı-zaman eğrisinin ilk bölümü için hangisi en doğrudur?', 'Buz eriyene kadar sıcaklık 0 °C civarında sabit kalır', ['Sıcaklık hemen oda sıcaklığına çıkar', 'Sıcaklık 0 °C\'nin altına inerek orada kalır', 'Sıcaklık hemen düşmeye başlar ve sürekli azalır'], 'Buz-su karışımı eriyene kadar sıcaklık yaklaşık 0 °C\'de kalır; ancak buz tamamen eridikten sonra sıcaklık yükselmeye başlar.'),
  ('Girdileri −2 ile 4 arasında, çıktıları 1 ile 3 arasında olan bir f\'nin eğrisi önce 1 birim sağa kaydırılıp sonra x eksenine göre yansıtılıyor. Yeni eğrinin y değerleri hangi aralıkta kalır?', '[−3, −1]', ['[1, 3]', '[−1, 3]', '[0, 2]'], 'Yatay öteleme görüntü kümesini değiştirmez; eksi işareti [1, 3]\'ü [−3, −1]\'e çevirir.'),
  ('[1, 5] aralığında yükselen bir f eğrisi dikey eksene göre aynalanıyor. Aynalanmış eğri, yani y = f(−x), hangi aralıkta alçalır?', '[−5, −1]', ['[1, 5]', '[−1, 5]', '[−5, 1]'], 'y eksenine göre yansıma artanlığı azalanlığa çevirir ve aralığı da yansıtır: [−5, −1].'),
  ('f\'nin yerel en büyük noktası (2, 7)\'dir. g(x) = f(x/2) + 1 fonksiyonunun yerel en büyük noktası nedir?', '(4, 8)', ['(1, 8)', '(4, 7)', '(1, 7)'], 'x/2 = 2 için x = 4\'tür; değer 7 + 1 = 8 olur.'),
  ('f\'nin grafiği y eksenini (0, 5) noktasında kesiyor. k(x) = f(x − 3) grafiğinin hangi noktası kesinlikle bilinir?', '(3, 5)', ['(0, 5)', '(−3, 5)', '(0, 2)'], 'k(3) = f(0) = 5\'tir; ancak k\'nin y eksenini nerede kestiği f(−3)\'e bağlıdır ve bilinmez.'),
  ('Düşey asimptotu x = −1 olan bir f\'nin girdisi 3 ile çarpılarak g(x) = f(3x) oluşturuluyor. g\'nin düşey asimptotu hangi doğrudur?', 'x = −1/3', ['x = −3', 'x = −1', 'x = 3'], '3x = −1 olduğunda g tanımsızlaşır; buradan x = −1/3 bulunur.'),
  ('Bir öğrenci y = f(x) grafiğini 2 birim sağa kaydırmak için kuralı y = f(x) + 2 olarak yazıyor. Bu yazımın gerçek etkisi nedir?', 'Grafiği 2 birim yukarı kaydırır', ['Grafiği x ekseni boyunca 2 birim sağa kaydırır', 'Grafiği 2 birim sola kaydırır', 'Grafiği 2 kat uzatır'], 'Fonksiyona sabit eklemek düşey ötelemedir. Sağa kaydırmak için x yerine x − 2 yazılmalıdır.'),
  ('Ortalama değişim hızı [0, 10]\'da 3 olan bir f\'nin bütün çıktıları 5 ile çarpılıyor. Yeni fonksiyonun bu aralıktaki ortalama değişim hızı ne olur?', '15', ['3', '8', '0,6'], 'Düşey uzatma değerleri ve dolayısıyla farkı 5 katına çıkarır; ortalama değişim hızı 15 olur.'),
  ('f(x) = 2ˣ ise g(x) = 2^(x + 3) fonksiyonu aynı zamanda f\'nin hangi düşey dönüşümüyle elde edilebilir?', 'Düşeyde 8 kat uzatmayla', ['3 birim yukarı ötelemeyle', 'Düşeyde 3 kat uzatmayla', '8 birim yukarı ötelemeyle'], '2^(x+3) = 2³·2ˣ = 8·2ˣ olduğundan 3 birim sola öteleme, 8 kat düşey uzatmaya eşittir.'),
  ('Bir kahvenin sıcaklık farkı (kahve − oda) her 10 dakikada yarıya iniyor. Oda 20 °C, kahve başta 84 °C ise 30 dakika sonra kahvenin sıcaklığı kaç °C\'dir?', '28', ['42', '21', '36'], 'Fark başta 64 °C\'dir; 3 yarılanmada 64 → 32 → 16 → 8 olur. Sıcaklık 20 + 8 = 28 °C\'dir.'),
  ('Bir yatırımcı \'Değeri her yıl %50 düşen bir hisse iki yıl sonra değersiz olur\' diyor. Bu iddia için doğru değerlendirme hangisidir?', 'Yanlıştır; değer çeyreğine iner ama sıfır olmaz', ['Doğrudur; %50 ile %50\'nin toplamı %100 kayıp anlamına gelir', 'Yanlıştır; değer yarıya iner', 'Doğrudur; ikinci yıl tüm değer kaybedilir'], 'Her yıl 0,5 ile çarpılır: 0,5² = 0,25. Üstel azalmada değer sıfıra yaklaşır ama ulaşmaz.'),
  ('Basit artışla f(x) = 100 + 10x, bileşik artışla g(x) = 100·1,1ˣ değerine ulaşan iki birikim x = 1\'de eşittir. Üçüncü yılın sonunda (x = 3) hangisi doğrudur?', 'g(3) > f(3)', ['f(3) > g(3)', 'f(3) = g(3)', 'İkisi de 100\'e eşittir'], 'f(3) = 130, g(3) = 100·1,331 = 133,1\'dir. Bileşik artış basit artışı geçer.'),
  ('Bir otomattan \'tuşa basınca rastgele bir içecek veriliyor\'. Tuş numarası ile verilen içecek arasındaki ilişki neden fonksiyon değildir?', 'Aynı tuş farklı zamanlarda farklı içecek verebilir', ['Bazı içecekler hiç verilmez', 'İki farklı tuş aynı içeceği verebildiği için eşleme bozulur', 'İçecek sayısı tuş sayısından fazladır'], 'Fonksiyon olmak için her girdinin tek ve belirli bir çıktısı olmalıdır; rastgelelik bu koşulu bozar.'),
  ('f fonksiyonu (−∞, 2)\'de pozitif, (2, ∞)\'da negatiftir; g fonksiyonu (−∞, −1)\'de negatif, (−1, ∞)\'da pozitiftir. f·g çarpımı hangi aralıkta pozitiftir?', '(−1, 2)', ['(−∞, −1)', '(2, ∞)', '(−∞, −1) ∪'], '−1 < x < 2\'de f ve g ikisi de pozitiftir. Diğer bölgelerde biri pozitif diğeri negatiftir.'),
  ('f(x) > 0 yalnız (0, 4) aralığında, f(x) < 0 ise yalnız (−∞, 0) ∪ (4, ∞) kümesinde sağlanıyor; g(x) > 0 her x için sağlanıyor. f(x)/g(x) < 0 eşitsizliği hangi kümede sağlanır?', '(−∞, 0) ∪', ['(0, 4)', '[0, 4]', 'Hiçbir x için sağlanmaz'], 'Payda her zaman pozitif olduğundan bölümün işareti f\'ninkiyle aynıdır. f, (−∞, 0) ∪ (4, ∞) kümesinde negatiftir.'),
  ('Bir öğrenci \'y = 5 bir fonksiyon değildir çünkü içinde x yok\' diyor. Bu iddia için doğru değerlendirme hangisidir?', 'Yanlıştır; her x\'e 5\'i karşılık getiren sabit fonksiyondur', ['Doğrudur; fonksiyonların kuralında x bulunmalıdır', 'Doğrudur; grafik düşey bir doğrudur', 'Yanlıştır; y = 5 birim fonksiyondur'], 'Kuralın x\'e bağlı olmaması sorun değildir; her girdinin tek çıktısı (5) vardır. Grafiği yatay doğrudur.'),
  ('Bir otoyolda hız sınırını aşan sürücüye ceza C(v), aşım 10 km/sa\'e kadar 0, 10–30 km/sa arası 1 000 TL, 30 km/sa\'ten fazlası 2 000 TL\'dir (sınır 120 km/sa). 135 km/sa ve 150 km/sa hızla giden iki sürücünün cezaları toplamı kaç TL\'dir?', '2 000', ['3 000', '4 000', '1 000'], '135 km/sa için aşım 15\'tir (1 000 TL), 150 km/sa için aşım 30\'dur ve 10–30 aralığında kalır (1 000 TL). Toplam 2 000 TL\'dir.'),
  ('Dördüncü kuvvete 1 eklenerek oluşan x⁴ + 1 ifadesinin eğrisi yatay eksenle kaç ortak noktaya sahiptir?', 'Hiç kesmez', ['1', '2', '4'], 'x⁴ ≥ 0 olduğundan x⁴ + 1 ≥ 1\'dir; grafik her yerde x ekseninin üstündedir.'),
  ('Eğrisi (a, b) noktasından geçen bir f, a birim sağa ve b birim yukarı taşınıyor: y = f(x − a) + b. Yeni eğride kesinlikle bulunan nokta hangisidir?', '(2a, 2b)', ['(0, 0)', '(a, b)', '(2a, b)'], 'x = 2a için f(2a − a) + b = f(a) + b = 2b olur.'),
  ('Bir kira sözleşmesinde aylık kira her yıl başında sabit 500 TL artıyor ve ilk yıl 8 000 TL\'dir. n. yıldaki aylık kirayı veren fonksiyon hangisidir?', 'K(n) = 7 500 + 500n', ['K(n) = 8 000 + 500n', 'K(n) = 8 000·1,5ⁿ', 'K(n) = 500n'], 'n = 1 için 8 000 olmalıdır; her yıl 500 eklendiğinden K(n) = 8 000 + 500(n − 1) = 7 500 + 500n\'dir.'),
  ('Periyodu 5 olan bir f fonksiyonunun [0, 5) aralığında tam 2 sıfırı vardır. f\'nin [0, 20) aralığında kaç sıfırı vardır?', '8', ['10', '4', '2'], '[0, 20) aralığı periyodun 4 tekrarını içerir; her tekrarda 2 sıfır vardır: 4·2 = 8.'),
  ('f fonksiyonu [−3, 3] aralığında tanımlı ve çifttir; [0, 3]\'te 0\'dan 6\'ya kesin artandır. f(x) = 4 denkleminin bu aralıkta kaç çözümü vardır?', '2', ['1', '3', '4'], '[0, 3]\'te f, 4 değerini tam bir kez alır. Çift olduğundan simetrik negatif noktada da 4 değeri alınır.'),
  ('Bir öğrenci \'f(x) = 3 denkleminin iki çözümü varsa f birebir değildir\' diyor. Bu yargı için doğru değerlendirme hangisidir?', 'Doğrudur; iki farklı girdi aynı çıktıyı vermektedir', ['Yanlıştır; birebirlik yalnız artanlıkla ilgilidir', 'Yanlıştır; f örten olmadığı için birebir olabilir', 'Doğrudur; ancak bu sonuç yalnız f doğrusal bir fonksiyonsa geçerlidir'], 'Birebirlik tanımı farklı girdilerin farklı çıktılara gitmesidir. f(a) = f(b) = 3, a ≠ b bunu bozar.'),
  ('Çıktıları −2 ile 2 arasında (uçlar dahil) değişen bir f\'nin çıktılarının karesi alınırsa elde edilen değerler hangi aralığı oluşturur?', '[0, 4]', ['[−4, 4]', '[0, 2]', '[−2, 4]'], 'f\'nin değerleri −2 ile 2 arasındadır; bunların kareleri 0 ile 4 arasında olur ve f sıfırı da aldığından 0 dahildir.'),
  ('|x| + |y| = 2 denklemini sağlayan (x, y) noktalarının oluşturduğu kapalı şekil için hangisi doğrudur?', 'Köşeleri eksenler üzerinde olan bir karedir ve fonksiyon grafiği değildir', ['Bir fonksiyonun V biçimli grafiğidir', 'Merkezi orijinde olan bir çemberdir', 'Eksenlerden birine paralel bir doğrudur'], '|x| + |y| = 2 her bölgede bir doğru parçası verir; birleşince köşeleri (±2, 0) ve (0, ±2) olan bir kare oluşur. Bir x\'e iki y karşılık geldiğinden fonksiyon değildir.'),
];
